INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginnt eine Link-Local-Adresse immer mit FE80::/10?', 2, '[{"text": "Ja", "correct": true, "because": "Standard für lokale Kommunikation"}, {"text": "Nein", "correct": false, "because": "Festgelegt im Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits sind bei FE80::/10 für den Präfix reserviert?', 3, '[{"text": "10", "correct": true, "because": "/10 definiert die ersten 10 Bits"}, {"text": "64", "correct": false, "because": "Typisch für Interface-ID"}, {"text": "128", "correct": false, "because": "Gesamtlänge der Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Zweck hat eine Adresse wie FE80::1?', 4, '[{"text": "Lokale Netzwerkkommunikation", "correct": true, "because": "Nur im gleichen Link gültig"}, {"text": "Globale Routing", "correct": false, "because": "Nicht routbar"}, {"text": "Multicast-Gruppen", "correct": false, "because": "Anderer Adresstyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Link-Local-Adressen sind nicht routbar. b) Sie benötigen eine Schnittstellen-ID.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Nicht routbar und schnittstellenspezifisch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von FE80::/10?', 5, '[{"text": "Globale Erreichbarkeit", "correct": true, "because": "Nur lokal gültig"}, {"text": "Schnittstellenangabe", "correct": false, "because": "Muss angegeben werden"}, {"text": "Hex-Format", "correct": false, "because": "Teil der Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Link-Local-Adressen manuell vergeben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisch generiert"}, {"text": "Ja", "correct": false, "because": "Typisch autokonfiguriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für lokale Kommunikation?', 3, '[{"text": "FE80::1", "correct": true, "because": "Link-Local-Standard"}, {"text": "2001:db8::1", "correct": false, "because": "Global Unicast"}, {"text": "FF00::1", "correct": false, "because": "Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat FE80::/10?', 5, '[{"text": "Nicht routbar", "correct": true, "because": "Nur im lokalen Link"}, {"text": "Schnittstellenspezifisch", "correct": true, "because": "Interface-ID nötig"}, {"text": "Global eindeutig", "correct": false, "because": "Nur lokal"}, {"text": "Für Gruppen", "correct": false, "because": "Nicht Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) FE80::/10 ist für jedes Gerät automatisch da. b) Sie ersetzt globale Adressen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt nur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Link-Local-Adresse?', 4, '[{"text": "Schnittstellen-ID", "correct": false, "because": "Muss angegeben werden"}, {"text": "FE80-Präfix", "correct": false, "because": "Definiert Typ"}, {"text": "Router-Zugriff", "correct": true, "because": "Nicht routbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Link-Local-Adressen weltweit eindeutig?', 2, '[{"text": "Nein", "correct": true, "because": "Nur lokal gültig"}, {"text": "Ja", "correct": false, "because": "Keine globale Reichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren eine lokale Adresse?', 4, '[{"text": "FE80::/10 Präfix", "correct": true, "because": "Standardkennung"}, {"text": "Schnittstellenbezug", "correct": true, "because": "Link-spezifisch"}, {"text": "Globale Routbarkeit", "correct": false, "because": "Nicht gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass FE80::1 ohne Interface-ID nutzlos ist. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Schnittstelle muss spezifiziert sein"}, {"text": "Nein", "correct": false, "because": "Interface-ID ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von FE80::/10?', 3, '[{"text": "Lokale Erreichbarkeit", "correct": true, "because": "Zweck der Adresse"}, {"text": "Globale Verbindung", "correct": false, "because": "Nicht routbar"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Link-Local wird automatisch generiert. b) Sie ist für WAN gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nur LAN"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet FE80::/10?', 5, '[{"text": "Automatische Konfiguration", "correct": true, "because": "SLAAC-fähig"}, {"text": "Lokale Kommunikation", "correct": true, "because": "Link-spezifisch"}, {"text": "Globale Reichweite", "correct": false, "because": "Nicht routbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei FE80::/10 unwichtig?', 3, '[{"text": "Schnittstellen-ID", "correct": false, "because": "Essenziell"}, {"text": "Präfix FE80", "correct": false, "because": "Definiert Typ"}, {"text": "Externe Routbarkeit", "correct": true, "because": "Nur lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann FE80::/10 über Router kommunizieren?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht routbar"}, {"text": "Ja", "correct": false, "because": "Nur lokaler Link"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FE80::/10 für Multicast genutzt wird?', 3, '[{"text": "Nein", "correct": true, "because": "Link-Local ist Unicast"}, {"text": "Ja", "correct": false, "because": "Multicast ist FF00::"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkung hat FE80::/10?', 4, '[{"text": "Nur lokaler Link", "correct": true, "because": "Nicht routbar"}, {"text": "Globale Eindeutigkeit", "correct": false, "because": "Nicht erforderlich"}, {"text": "Manuelle Vergabe", "correct": false, "because": "Automatisch"}]');
